123	TEST_CASE("csr_trigger: 2-byte stride skips compressed insns and aligns 4-byte insns")
124	{
125	  // Layout:
126	  //   0x80000000: c.addi x1, 1     (2 bytes, RVC: bits[1:0] != 0b11)
127	  //   0x80000002: csrwi 0x7C0, 1   (4 bytes)
128	  //   0x80000006: c.nop            (2 bytes)
129	  hybrid::CsrTrigger trig;
130	  alignas(uint32_t) std::array<uint8_t, 8> bytes{};
131	  // c.addi x1, 1 = 0x0085 (op=01, funct3=000, rd=x1, imm=1) -- rvc bits[1:0]=01
132	  // Use a placeholder 16-bit RVC pattern: 0x0085
133	  bytes[0] = 0x85;
134	  bytes[1] = 0x00;
135	  // csrwi 0x7C0, 1 = 0x7C00D073 (little-endian: 73 D0 00 7C)
136	  const uint32_t exit_insn = encode_csrrwi(0, 0x7C0, 1);
137	  std::memcpy(&bytes[2], &exit_insn, sizeof(exit_insn));
138	  // c.nop = 0x0001 (rvc bits[1:0]=01)
139	  bytes[6] = 0x01;
140	  bytes[7] = 0x00;
141	
142	  trig.scan_buffer(std::span<const uint8_t>{bytes.data(), bytes.size()},
143	                   /*base_pc=*/0x80000000);
144	
145	  // Only the 4-byte csrwi at 0x80000002 should match.
146	  CHECK_FALSE(trig.lookup(0x80000000).has_value());
